// Bounded command-line orchestration only. Policy, source validation, funded
// accounting and durability execute inside the pinned Rust observer.
import fs from'node:fs';import path from'node:path';import{createHash}from'node:crypto';import{spawnSync}from'node:child_process';
const rt=path.join(process.env.LOCALAPPDATA,'SigTradingCup/paper-runtime'),prepared=JSON.parse(fs.readFileSync('data/native-receipt-observer-prepared-20261006.json')),dir=path.join(rt,'settlement-portfolio-v3-cohorts',prepared.cohort),bank=JSON.parse(fs.readFileSync(path.join(dir,'bank.json'))),binary=path.join(rt,prepared.binaryRelative),source=path.join(rt,'public-books.jsonl'),markets=new Set(bank.research.map(r=>r.marketId));
if(createHash('sha256').update(fs.readFileSync(binary)).digest('hex')!==prepared.serviceBinaryHash)throw Error('Pinned observer binary changed');const started=Date.now();let trigger=null;
while(Date.now()-started<45000){for(const n of['STOP','COLLECTOR_STOP','EXECUTION_STOP'])if(fs.existsSync(path.join(rt,n)))throw Error('STOP provenance review required');if(fs.existsSync(path.join(dir,'STOP')))throw Error('Cohort STOP');const consumed=JSON.parse(fs.readFileSync(path.join(dir,'stats.json'))).observer.sourceSequence,size=fs.statSync(source).size,n=Math.min(size,1024*1024),buffer=Buffer.alloc(n),fd=fs.openSync(source,'r');try{fs.readSync(fd,buffer,0,n,size-n);}finally{fs.closeSync(fd);}const end=buffer.lastIndexOf(10),rows=buffer.subarray(0,end).toString().split('\n');if(n<size)rows.shift();for(let i=rows.length-1;i>=0;i--){const r=JSON.parse(rows[i]);if(r.sequence<=consumed)break;if(r.kind==='book'&&markets.has(r.payload.book.marketId)){const age=Date.now()-Date.parse(r.payload.book.receivedAt);if(age>=0&&age<=5000){trigger={sourceSequence:r.sequence,ageMs:age};break;}}}if(trigger)break;await new Promise(resolve=>setTimeout(resolve,500));}
if(!trigger){console.log(JSON.stringify({status:'no_fresh_unconsumed_source_within_bound',accountRequests:0,competitionOrders:0}));process.exitCode=2;}else{const result=spawnSync(binary,['--observer-config',path.join(rt,prepared.configFileRelative),'--consume-once','--maximum-rows','4096'],{encoding:'utf8',windowsHide:true,timeout:60000,maxBuffer:1024*1024});if(result.status!==0)throw Error('Native observer failed: '+result.stderr.trim());console.log(JSON.stringify({trigger,waitMs:Date.now()-started,result:JSON.parse(result.stdout.trim()),persistentServicesAdded:0,accountRequests:0}));}
